function hero(title, id, home = false) {
  return `<section class="hero${home?' home':''}${['Linea Smart','Smart S1'].includes(title)?' blue':''}" aria-label="${title}">${home?`<div class="hero-media"><video autoplay muted loop playsinline poster="assets/c6dcabc9ce6250c20c009b3fc8dab711.webp" aria-label="Lavorazione dei sistemi Canaletto"><source src="assets/hero.mp4" type="video/mp4"></video></div>`:image(id,title)}<h1>${home?'Luce <span>come</span> <span>linguaggio</span>':title}</h1>${home?`<a class="discovery" href="#catalogo">${image('940f6b7a5b29ce7741c702f3120404a0','Sistema integrato Canaletto')}<span>Scopri<br>i nostri sistemi${icon('arrow-right')}</span></a>`:''}</section>`;
}
const intro = (title, copy = '', button = '') => `<section class="intro"><h2>${title}</h2>${copy?`<p>${copy}</p>`:''}${button}</section>`;
// Chi siamo: foto a tutto schermo con i titoli dei valori; lo scroll (motion.js) la trasforma nella griglia.
const aboutHero = items => `<section class="about-hero" aria-labelledby="about-title"><h1 id="about-title" class="about-hero-title">Chi siamo</h1><div class="about-hero-media">${image('11874c90c311dff48f377e631c02ddad','Chi siamo')}</div><div class="about-hero-stage"><div class="container about-pillars">${items.map(([title,copy])=>`<article><h2>${title}.</h2><p>${copy}</p></article>`).join('')}</div></div></section>`;
const features = items => `<div class="container feature-grid">${items.map(([title,copy,glyph])=>`<article class="feature">${icon(glyph)}<h3>${title}</h3><p>${copy}</p></article>`).join('')}</div>`;
const band = (id,title,copy,button,short=false) => `<section class="image-band${short?' short':''}">${image(id,title)}<div class="band-content"><h2>${title}</h2><p>${copy}</p>${button}</div></section>`;
function lineGrid() {return `<section class="container section line-section" id="linee"><h2>Trova la soluzione per il tuo progetto.</h2><p>Ogni dettaglio conta.<br>Esplora le nostre linee e individua il sistema più adatto alle tue esigenze di progettazione e installazione.</p><div class="line-grid">${lines.map(l=>`<a href="#${l.name==='Smart'?'linea-smart':'linea-'+l.name.toLowerCase()}" class="line-card"><h3>Linea ${l.name}</h3><p>${l.desc}</p>${image(l.id,'Sezione del profilo Linea '+l.name)}<span class="arrow">${icon('arrow-right')}</span></a>`).join('')}</div></section>`;}
function guideBand() {return `<section class="guide-band"><span class="eyebrow">Guida alla scelta</span><h2>Quale soluzione serve al tuo progetto?</h2><p>Parti dall’effetto che vuoi ottenere.</p><div class="guide-choices">${[['sun','Luce indiretta'],['scan-line','Tagli di luce'],['layers','Finiture architettoniche']].map(([i,t])=>`<button class="guide-choice" data-action="guide">${icon(i)}${t}</button>`).join('')}</div>${action('Trova il profilo giusto','guide','button dark')}</section>`;}
function projectCloud(){
 const ids=[...photos.project1,...photos.project2,...photos.project3,...photos.project4,...photos.s1.slice(3)];
 const positions=[[6,14],[20,4],[32,22],[72,8],[88,18],[12,43],[25,72],[39,86],[64,82],[81,64],[94,44],[4,88],[75,38],[52,94]];
 const sizes=[64,88,112,56,96,76,120];
 const tiles=[...ids,...ids].map((id,i)=>{
  const slot=positions[i%positions.length];
  const x=i<ids.length?slot[0]:(slot[0]+11)%96;
  const y=i<ids.length?slot[1]:(slot[1]+43)%100;
  return `<div class="cloud-particle" data-cloud-seed="${y}" style="left:${x}%;top:${y}%;--tile-size:${sizes[i%sizes.length]}px;--tile-opacity:${[.38,.65,.9,.28,.8][i%5]}"><img src="assets/${id}.webp" alt="" loading="lazy" decoding="async"></div>`;
 }).join('');
 return `<section class="project-cloud" aria-labelledby="cloud-title"><div class="cloud-field" aria-hidden="true">${tiles}</div><div class="cloud-copy"><h2 id="cloud-title">Diamo luce alle idee.<br>Spazio dopo spazio.</h2>${link('Esplora i progetti','progetti')}</div></section>`;
}
